values
  ('Modern Restaurant', 'modern-restaurant', 'restaurant-food', 'Polished restaurant homepage with menu presentation, reservations, location and gallery sections for modern dining businesses.', 'Polished restaurant homepage with menu presentation, reservations, location and gallery sections for modern dining businesses. Includes a responsive layout, editable sections and a premium visual style ready to launch.', '/templates/modern-restaurant.webp', '/templates/modern-restaurant-full.jpg', '', ARRAY['restaurant', 'dining', 'menu', 'reservations']::text[], true, 'published', 1, '{"title": "Modern Restaurant Website Template", "og_image": "/templates/modern-restaurant-full.jpg", "description": "Modern Restaurant website template — polished restaurant homepage with menu presentation, reservations, location and gallery sections for modern dining businesses. Preview the design and start with this template at BRANIFY."}'::jsonb),
  ('SORA Restaurant', 'sora-restaurant', 'restaurant-food', 'Editorial restaurant design with tasting-menu storytelling, chef profile and elegant food photography layouts.', 'Editorial restaurant design with tasting-menu storytelling, chef profile and elegant food photography layouts. Includes a responsive layout, editable sections and a premium visual style ready to launch.', '/templates/sora-restaurant.webp', '/templates/sora-restaurant-full.jpg', '', ARRAY['restaurant', 'tasting menu', 'chef', 'editorial']::text[], false, 'published', 2, '{"title": "SORA Restaurant Website Template", "og_image": "/templates/sora-restaurant-full.jpg", "description": "SORA Restaurant website template — editorial restaurant design with tasting-menu storytelling, chef profile and elegant food photography layouts. Preview the design and start with this template at BRANIFY."}'::jsonb),
  ('MAISON French Dining', 'maison-fine-dining', 'restaurant-food', 'Refined French fine-dining template with tasting menus, private dining section and editorial serif typography.', 'Refined French fine-dining template with tasting menus, private dining section and editorial serif typography. Includes a responsive layout, editable sections and a premium visual style ready to launch.', '/templates/maison-fine-dining.webp', '/templates/maison-fine-dining-full.jpg', '', ARRAY['french', 'fine dining', 'tasting menu', 'private dining']::text[], true, 'published', 4, '{"title": "MAISON French Dining Website Template", "og_image": "/templates/maison-fine-dining-full.jpg", "description": "MAISON French Dining website template — refined French fine-dining template with tasting menus, private dining section and editorial serif typography. Preview the design and start with this template at BRANIFY."}'::jsonb),
  ('STREET Street Food', 'street-street-food', 'restaurant-food', 'High-energy street food template with best-seller menu, brand story and online ordering call-to-action.', 'High-energy street food template with best-seller menu, brand story and online ordering call-to-action. Includes a responsive layout, editable sections and a premium visual style ready to launch.', '/templates/street-street-food.webp', '/templates/street-street-food-full.jpg', '', ARRAY['street food', 'burger', 'ordering', 'casual dining']::text[], false, 'published', 5, '{"title": "STREET Street Food Website Template", "og_image": "/templates/street-street-food-full.jpg", "description": "STREET Street Food website template — high-energy street food template with best-seller menu, brand story and online ordering call-to-action. Preview the design and start with this template at BRANIFY."}'::jsonb),
