  ('Luxury Beauty Salon', 'luxury-beauty-salon', 'beauty-salon', 'Premium salon template with service menus, stylist profiles, pricing tiers and booking call-to-action.', 'Premium salon template with service menus, stylist profiles, pricing tiers and booking call-to-action. Includes a responsive layout, editable sections and a premium visual style ready to launch.', '/templates/luxury-beauty-salon.webp', '/templates/luxury-beauty-salon-full.jpg', '', ARRAY['salon', 'beauty', 'booking', 'services']::text[], true, 'published', 11, '{"title": "Luxury Beauty Salon Website Template", "og_image": "/templates/luxury-beauty-salon-full.jpg", "description": "Luxury Beauty Salon website template — premium salon template with service menus, stylist profiles, pricing tiers and booking call-to-action. Preview the design and start with this template at BRANIFY."}'::jsonb),
  ('Luxury Dental Clinic', 'luxury-dental-clinic', 'healthcare-medical', 'Premium dental clinic template with treatment pages, smile galleries and appointment request funnels.', 'Premium dental clinic template with treatment pages, smile galleries and appointment request funnels. Includes a responsive layout, editable sections and a premium visual style ready to launch.', '/templates/luxury-dental-clinic.webp', '/templates/luxury-dental-clinic-full.jpg', '', ARRAY['dental', 'clinic', 'appointments', 'treatments']::text[], false, 'published', 12, '{"title": "Luxury Dental Clinic Website Template", "og_image": "/templates/luxury-dental-clinic-full.jpg", "description": "Luxury Dental Clinic website template — premium dental clinic template with treatment pages, smile galleries and appointment request funnels. Preview the design and start with this template at BRANIFY."}'::jsonb),
