  ('BALANCE Wellness Platform', 'balance-wellness', 'fitness-lifestyle', 'Lifestyle wellness template with movement, nutrition and recovery programs plus membership pricing.', 'Lifestyle wellness template with movement, nutrition and recovery programs plus membership pricing. Includes a responsive layout, editable sections and a premium visual style ready to launch.', '/templates/balance-wellness.webp', '/templates/balance-wellness-full.jpg', '', ARRAY['wellness', 'lifestyle', 'membership', 'nutrition']::text[], false, 'published', 22, '{"title": "BALANCE Wellness Platform Website Template", "og_image": "/templates/balance-wellness-full.jpg", "description": "BALANCE Wellness Platform website template — lifestyle wellness template with movement, nutrition and recovery programs plus membership pricing. Preview the design and start with this template at BRANIFY."}'::jsonb),
