  ('STRATEGY Consulting Firm', 'strategy-consulting-firm', 'business-services', 'Strategy consulting template with capability areas, industry expertise, engagement roadmap and global office locations.', 'Strategy consulting template with capability areas, industry expertise, engagement roadmap and global office locations. Includes a responsive layout, editable sections and a premium visual style ready to launch.', '/templates/strategy-consulting-firm.webp', '/templates/strategy-consulting-firm-full.jpg', '', ARRAY['consulting', 'strategy', 'b2b', 'advisory']::text[], false, 'published', 100, '{"title": "STRATEGY Consulting Firm Website Template", "og_image": "/templates/strategy-consulting-firm-full.jpg", "description": "STRATEGY Consulting Firm website template — strategy consulting template with capability areas, industry expertise, engagement roadmap and global office locations. Preview the design and start with this template at BRANIFY."}'::jsonb),
  ('FINCOUNT Accounting & Advisory', 'fincount-accounting', 'business-services', 'Accounting firm template with audit, CFO advisory, business structuring, client journey timeline and reporting hub.', 'Accounting firm template with audit, CFO advisory, business structuring, client journey timeline and reporting hub. Includes a responsive layout, editable sections and a premium visual style ready to launch.', '/templates/fincount-accounting.webp', '/templates/fincount-accounting-full.jpg', '', ARRAY['accounting', 'audit', 'cfo advisory', 'finance']::text[], false, 'published', 101, '{"title": "FINCOUNT Accounting & Advisory Website Template", "og_image": "/templates/fincount-accounting-full.jpg", "description": "FINCOUNT Accounting & Advisory website template — accounting firm template with audit, CFO advisory, business structuring, client journey timeline and reporting hub. Preview the design and start with this template at BRANIFY."}'::jsonb),
  ('EDORA Online Learning', 'edora-online-learning', 'education', 'Premium learning platform template with curated courses, learning paths, expert instructors and certification pricing tiers.', 'Premium learning platform template with curated courses, learning paths, expert instructors and certification pricing tiers. Includes a responsive layout, editable sections and a premium visual style ready to launch.', '/templates/edora-online-learning.webp', '/templates/edora-online-learning-full.jpg', '', ARRAY['courses', 'e-learning', 'learning paths', 'certificates']::text[], true, 'published', 102, '{"title": "EDORA Online Learning Website Template", "og_image": "/templates/edora-online-learning-full.jpg", "description": "EDORA Online Learning website template — premium learning platform template with curated courses, learning paths, expert instructors and certification pricing tiers. Preview the design and start with this template at BRANIFY."}'::jsonb),
  ('FIXO Home Repairs', 'fixo-home-repairs', 'home-services', 'Plumbing and electrical repair template with service grids, 24/7 emergency banner, booking forms and certified technician trust sections.', 'Plumbing and electrical repair template with service grids, 24/7 emergency banner, booking forms and certified technician trust sections. Includes a responsive layout, editable sections and a premium visual style ready to launch.', '/templates/fixo-home-repairs.webp', '/templates/fixo-home-repairs-full.jpg', '', ARRAY['repairs', 'plumbing', 'electrical', 'booking']::text[], false, 'published', 103, '{"title": "FIXO Home Repairs Website Template", "og_image": "/templates/fixo-home-repairs-full.jpg", "description": "FIXO Home Repairs website template — plumbing and electrical repair template with service grids, 24/7 emergency banner, booking forms and certified technician trust sections. Preview the design and start with this template at BRANIFY."}'::jsonb),
