  ('GARAGE Auto Service', 'garage-auto-service', 'automotive', 'Precision auto service template with maintenance pillars, booking scheduler, service pricing plans and certified technician sections.', 'Precision auto service template with maintenance pillars, booking scheduler, service pricing plans and certified technician sections. Includes a responsive layout, editable sections and a premium visual style ready to launch.', '/templates/garage-auto-service.webp', '/templates/garage-auto-service-full.jpg', '', ARRAY['garage', 'auto repair', 'maintenance', 'booking']::text[], false, 'published', 105, '{"title": "GARAGE Auto Service Website Template", "og_image": "/templates/garage-auto-service-full.jpg", "description": "GARAGE Auto Service website template — precision auto service template with maintenance pillars, booking scheduler, service pricing plans and certified technician sections. Preview the design and start with this template at BRANIFY."}'::jsonb),
  ('FORGE Strength Gym', 'forge-strength-gym', 'fitness-lifestyle', 'Gritty strength gym template with training programs, coach profiles, weekly class schedule, membership tiers and transformation results.', 'Gritty strength gym template with training programs, coach profiles, weekly class schedule, membership tiers and transformation results. Includes a responsive layout, editable sections and a premium visual style ready to launch.', '/templates/forge-strength-gym.webp', '/templates/forge-strength-gym-full.jpg', '', ARRAY['gym', 'strength', 'classes', 'membership']::text[], true, 'published', 106, '{"title": "FORGE Strength Gym Website Template", "og_image": "/templates/forge-strength-gym-full.jpg", "description": "FORGE Strength Gym website template — gritty strength gym template with training programs, coach profiles, weekly class schedule, membership tiers and transformation results. Preview the design and start with this template at BRANIFY."}'::jsonb),
  ('PLATTER Corporate Catering', 'platter-corporate-catering', 'catering-services', 'Corporate catering homepage with order-and-quote interface, breakfast-to-buffet menus, service packages and sector coverage for business events.', 'Corporate catering homepage with order-and-quote interface, breakfast-to-buffet menus, service packages and sector coverage for business events. Includes a responsive layout, editable sections and a premium visual style ready to launch.', '/templates/platter-corporate-catering.webp', '/templates/platter-corporate-catering-full.jpg', '', ARRAY['corporate catering', 'business events', 'quote', 'office lunches']::text[], true, 'published', 107, '{"title": "PLATTER Corporate Catering Website Template", "og_image": "/templates/platter-corporate-catering-full.jpg", "description": "PLATTER Corporate Catering website template — corporate catering homepage with order-and-quote interface, breakfast-to-buffet menus, service packages and sector coverage for business events. Preview the design and start with this template at BRANIFY."}'::jsonb),
  ('HARVEST Farm-to-Table Catering', 'harvest-farm-catering', 'catering-services', 'Farm-to-table catering design with seasonal menus, ingredient stories, farm partner profiles and event enquiry flows.', 'Farm-to-table catering design with seasonal menus, ingredient stories, farm partner profiles and event enquiry flows. Includes a responsive layout, editable sections and a premium visual style ready to launch.', '/templates/harvest-farm-catering.webp', '/templates/harvest-farm-catering-full.jpg', '', ARRAY['farm to table', 'seasonal menu', 'catering', 'events']::text[], false, 'published', 108, '{"title": "HARVEST Farm-to-Table Catering Website Template", "og_image": "/templates/harvest-farm-catering-full.jpg", "description": "HARVEST Farm-to-Table Catering website template — farm-to-table catering design with seasonal menus, ingredient stories, farm partner profiles and event enquiry flows. Preview the design and start with this template at BRANIFY."}'::jsonb),
  ('GRAZE Grazing Tables', 'graze-grazing-tables', 'catering-services', 'Artisan grazing table showcase with signature collections, party platters, dessert tables and booking call-to-action.', 'Artisan grazing table showcase with signature collections, party platters, dessert tables and booking call-to-action. Includes a responsive layout, editable sections and a premium visual style ready to launch.', '/templates/graze-grazing-tables.webp', '/templates/graze-grazing-tables-full.jpg', '', ARRAY['grazing table', 'platters', 'events', 'artisan food']::text[], false, 'published', 109, '{"title": "GRAZE Grazing Tables Website Template", "og_image": "/templates/graze-grazing-tables-full.jpg", "description": "GRAZE Grazing Tables website template — artisan grazing table showcase with signature collections, party platters, dessert tables and booking call-to-action. Preview the design and start with this template at BRANIFY."}'::jsonb),
  ('TABLE & CO. Event Catering', 'table-and-co-events', 'catering-services', 'Upscale event catering template with approach story, curated menus, chef profile and enquiry-first event planning.', 'Upscale event catering template with approach story, curated menus, chef profile and enquiry-first event planning. Includes a responsive layout, editable sections and a premium visual style ready to launch.', '/templates/table-and-co-events.webp', '/templates/table-and-co-events-full.jpg', '', ARRAY['event catering', 'weddings', 'menus', 'venues']::text[], false, 'published', 110, '{"title": "TABLE & CO. Event Catering Website Template", "og_image": "/templates/table-and-co-events-full.jpg", "description": "TABLE & CO. Event Catering website template — upscale event catering template with approach story, curated menus, chef profile and enquiry-first event planning. Preview the design and start with this template at BRANIFY."}'::jsonb),
  ('SERVE Private Chef Dining', 'serve-private-chef', 'catering-services', 'Private chef experience site with in-home dining menus, chef profile, step-by-step dining process and reservation enquiry.', 'Private chef experience site with in-home dining menus, chef profile, step-by-step dining process and reservation enquiry. Includes a responsive layout, editable sections and a premium visual style ready to launch.', '/templates/serve-private-chef.webp', '/templates/serve-private-chef-full.jpg', '', ARRAY['private chef', 'fine dining', 'home dining', 'reservations']::text[], false, 'published', 111, '{"title": "SERVE Private Chef Dining Website Template", "og_image": "/templates/serve-private-chef-full.jpg", "description": "SERVE Private Chef Dining website template — private chef experience site with in-home dining menus, chef profile, step-by-step dining process and reservation enquiry. Preview the design and start with this template at BRANIFY."}'::jsonb),
  ('FEAST Wedding Catering', 'feast-wedding-catering', 'catering-services', 'Luxury wedding catering template with menu storytelling, bar and cake services, real wedding stories and proposal requests.', 'Luxury wedding catering template with menu storytelling, bar and cake services, real wedding stories and proposal requests. Includes a responsive layout, editable sections and a premium visual style ready to launch.', '/templates/feast-wedding-catering.webp', '/templates/feast-wedding-catering-full.jpg', '', ARRAY['wedding catering', 'weddings', 'menus', 'banquet']::text[], true, 'published', 112, '{"title": "FEAST Wedding Catering Website Template", "og_image": "/templates/feast-wedding-catering-full.jpg", "description": "FEAST Wedding Catering website template — luxury wedding catering template with menu storytelling, bar and cake services, real wedding stories and proposal requests. Preview the design and start with this template at BRANIFY."}'::jsonb),
  ('VELVET Hair Salon', 'velvet-hair-salon', 'beauty-salon', 'Editorial hair salon template with signature services, color spectrum, before-after transformations and product shop.', 'Editorial hair salon template with signature services, color spectrum, before-after transformations and product shop. Includes a responsive layout, editable sections and a premium visual style ready to launch.', '/templates/velvet-hair-salon.webp', '/templates/velvet-hair-salon-full.jpg', '', ARRAY['hair salon', 'styling', 'color', 'book online']::text[], false, 'published', 113, '{"title": "VELVET Hair Salon Website Template", "og_image": "/templates/velvet-hair-salon-full.jpg", "description": "VELVET Hair Salon website template — editorial hair salon template with signature services, color spectrum, before-after transformations and product shop. Preview the design and start with this template at BRANIFY."}'::jsonb),
  ('BLUSH Beauty Studio', 'blush-beauty-studio', 'beauty-salon', 'Soft-glam beauty studio homepage with makeup, skincare, hair and nail services, beauty packages and booking flows.', 'Soft-glam beauty studio homepage with makeup, skincare, hair and nail services, beauty packages and booking flows. Includes a responsive layout, editable sections and a premium visual style ready to launch.', '/templates/blush-beauty-studio.webp', '/templates/blush-beauty-studio-full.jpg', '', ARRAY['beauty studio', 'makeup', 'skincare', 'booking']::text[], false, 'published', 114, '{"title": "BLUSH Beauty Studio Website Template", "og_image": "/templates/blush-beauty-studio-full.jpg", "description": "BLUSH Beauty Studio website template — soft-glam beauty studio homepage with makeup, skincare, hair and nail services, beauty packages and booking flows. Preview the design and start with this template at BRANIFY."}'::jsonb),
  ('GLOW Beauty Bar', 'glow-beauty-bar', 'beauty-salon', 'Express beauty bar layout with quick services, membership tiers, expert team, before-after results and online booking.', 'Express beauty bar layout with quick services, membership tiers, expert team, before-after results and online booking. Includes a responsive layout, editable sections and a premium visual style ready to launch.', '/templates/glow-beauty-bar.webp', '/templates/glow-beauty-bar-full.jpg', '', ARRAY['beauty bar', 'blow dry', 'nails', 'membership']::text[], false, 'published', 115, '{"title": "GLOW Beauty Bar Website Template", "og_image": "/templates/glow-beauty-bar-full.jpg", "description": "GLOW Beauty Bar website template — express beauty bar layout with quick services, membership tiers, expert team, before-after results and online booking. Preview the design and start with this template at BRANIFY."}'::jsonb),
  ('AURA Beauty Lounge', 'aura-beauty-lounge', 'beauty-salon', 'Premium facial and skincare lounge with treatment menus, skin philosophy, specialist profiles and results gallery.', 'Premium facial and skincare lounge with treatment menus, skin philosophy, specialist profiles and results gallery. Includes a responsive layout, editable sections and a premium visual style ready to launch.', '/templates/aura-beauty-lounge.webp', '/templates/aura-beauty-lounge-full.jpg', '', ARRAY['facial', 'skincare', 'beauty lounge', 'treatments']::text[], false, 'published', 116, '{"title": "AURA Beauty Lounge Website Template", "og_image": "/templates/aura-beauty-lounge-full.jpg", "description": "AURA Beauty Lounge website template — premium facial and skincare lounge with treatment menus, skin philosophy, specialist profiles and results gallery. Preview the design and start with this template at BRANIFY."}'::jsonb),
  ('FORM Unisex Salon', 'form-unisex-salon', 'beauty-salon', 'Bold unisex salon template with women''s and men''s services, lookbook, team profiles, product essentials and online booking.', 'Bold unisex salon template with women''s and men''s services, lookbook, team profiles, product essentials and online booking. Includes a responsive layout, editable sections and a premium visual style ready to launch.', '/templates/form-unisex-salon.webp', '/templates/form-unisex-salon-full.jpg', '', ARRAY['unisex salon', 'grooming', 'styling', 'lookbook']::text[], true, 'published', 117, '{"title": "FORM Unisex Salon Website Template", "og_image": "/templates/form-unisex-salon-full.jpg", "description": "FORM Unisex Salon website template — bold unisex salon template with women''s and men''s services, lookbook, team profiles, product essentials and online booking. Preview the design and start with this template at BRANIFY."}'::jsonb),
  ('CANTINA Modern Trattoria', 'cantina-trattoria', 'restaurant-food', 'Warm Italian trattoria template with handmade pasta menu storytelling, private dining, curated wine pairings and table reservations.', 'Warm Italian trattoria template with handmade pasta menu storytelling, private dining, curated wine pairings and table reservations. Includes a responsive layout, editable sections and a premium visual style ready to launch.', '/templates/cantina-trattoria.webp', '/templates/cantina-trattoria-full.jpg', '', ARRAY['italian', 'trattoria', 'private dining', 'reservations']::text[], false, 'published', 118, '{"title": "CANTINA Modern Trattoria Website Template", "og_image": "/templates/cantina-trattoria-full.jpg", "description": "CANTINA Modern Trattoria website template — warm Italian trattoria template with handmade pasta menu storytelling, private dining, curated wine pairings and table reservations. Preview the design and start with this template at BRANIFY."}'::jsonb),
  ('EMBER Steakhouse', 'ember-steakhouse', 'restaurant-food', 'Fire-driven steakhouse template with signature cuts menu, open-kitchen storytelling, wine pairings and reservation-first calls to action.', 'Fire-driven steakhouse template with signature cuts menu, open-kitchen storytelling, wine pairings and reservation-first calls to action. Includes a responsive layout, editable sections and a premium visual style ready to launch.', '/templates/ember-steakhouse.webp', '/templates/ember-steakhouse-full.jpg', '', ARRAY['steakhouse', 'grill', 'wine pairing', 'reservations']::text[], false, 'published', 119, '{"title": "EMBER Steakhouse Website Template", "og_image": "/templates/ember-steakhouse-full.jpg", "description": "EMBER Steakhouse website template — fire-driven steakhouse template with signature cuts menu, open-kitchen storytelling, wine pairings and reservation-first calls to action. Preview the design and start with this template at BRANIFY."}'::jsonb)
insert into public.services (slug, number, title, subtitle, description, icon, category, technologies, deliverables, stat_label, stat_value, price_note, active, featured, sort_order, seo, archived)
values
  ('website-development', '01', 'Website Development', 'High-performance React, Next.js & modern full-stack web applications.', 'We craft high-converting, modern web applications built on cutting-edge technologies like React, TypeScript, Next.js, Node.js, and Express. Whether you need an elite corporate web platform, a modern SaaS product, or a custom full-stack web portal, BRANIFY delivers pixel-perfect, secure, and lightning-fast solutions.', 'Globe', 'web', ARRAY['React', 'TypeScript', 'Next.js', 'Tailwind CSS', 'Node.js', 'Vite', 'PostgreSQL']::text[], ARRAY['Production Web Application Build', 'Full Source Code Repository', 'Admin Setup & Config', 'SEO Configuration', 'User Guide & Documentation Video']::text[], 'Starting price', 'Custom quote', '5–14 Days', true, true, 0, '{"title": "Website Development Services — BRANIFY", "description": "Custom, blazing-fast, responsive web applications engineered for conversions, SEO, and international scalability."}'::jsonb, false),
  ('wordpress-development', '02', 'WordPress Development', 'Custom Elementor, WooCommerce & headless WordPress solutions.', 'Power your business with the world’s most versatile CMS. We build ultra-fast, tailored WordPress & WooCommerce stores that are easy for your team to manage, fully secured against vulnerabilities, and optimized for search engine rankings.', 'LayoutGrid', 'web', ARRAY['WordPress', 'PHP', 'WooCommerce', 'Elementor Pro', 'MySQL', 'Redis']::text[], ARRAY['Custom WordPress Build', 'WooCommerce Setup', 'Licensed Plugin Setup', 'Speed Optimization Audit Report', 'Admin Training Video']::text[], 'Starting price', 'Custom quote', '4–14 Days', true, true, 1, '{"title": "WordPress Development Services — BRANIFY", "description": "Scalable, secure, and user-friendly WordPress websites with custom themes, Elementor Pro, WooCommerce, and speed optimization."}'::jsonb, false),
  ('landing-pages', '03', 'Landing Pages', 'High-converting lead generation & product launch pages.', 'Stop wasting ad spend on low-converting pages. BRANIFY crafts hyper-focused landing pages engineered around direct-response design principles, clear calls-to-action, mobile ergonomics, and instant loading speeds.', 'MousePointerClick', 'web', ARRAY['React', 'TypeScript', 'Tailwind CSS', 'Figma', 'Webhooks']::text[], ARRAY['High-Converting Landing Page Build', 'Persuasive Copywriting Outline', 'CRM & Webhook Integration', 'Pixel & Analytics Setup']::text[], 'Starting price', 'Custom quote', '3–7 Days', true, true, 2, '{"title": "Landing Pages Services — BRANIFY", "description": "Psychology-driven, fast-loading landing pages designed to turn ad traffic into paying customers and qualified leads."}'::jsonb, false),
  ('ui-ux-design', '04', 'UI/UX Design', 'User-centric research, wireframes & high-fidelity Figma design systems.', 'Great software starts with exceptional user experience. We combine user research, wireframing, interactive prototyping, and reusable Figma design systems to turn complex workflows into delightful, effortless digital products.', 'Figma', 'design', ARRAY['Figma', 'FigJam', 'Design Tokens', 'Auto-Layout']::text[], ARRAY['Figma Source File', 'Interactive Prototype Link', 'Design System Library', 'Asset Exports (SVG/PNG)']::text[], 'Starting price', 'Custom quote', '4–14 Days', true, false, 3, '{"title": "UI/UX Design Services — BRANIFY", "description": "Elevate your web or mobile product with intuitive user experience mapping, sleek visual design systems, and Figma prototypes."}'::jsonb, false),
  ('logo-design', '05', 'Logo Design', 'Memorable, modern, and vector-perfect brand logos.', 'Your logo is the visual cornerstone of your brand. Our designers craft unique, conceptual logo marks that communicate authority, trust, and distinction across digital screens, business cards, merchandise, and billboards.', 'Palette', 'branding', ARRAY['Adobe Illustrator', 'Figma', 'Vector Engine']::text[], ARRAY['Vector Master Files (AI, EPS, SVG, PDF)', 'High-Res PNG & JPG Packs', 'Favicon & App Icon Formats', 'Commercial Copyright Transfer']::text[], 'Starting price', 'Custom quote', '2–5 Days', true, false, 4, '{"title": "Logo Design Services — BRANIFY", "description": "Distill your business essence into an iconic, timeless, and versatile vector logo that stands out across print and digital media."}'::jsonb, false),
  ('brand-identity', '06', 'Brand Identity', 'Complete visual branding: guidelines, typography & social kits.', 'In today’s crowded marketplace, visual consistency builds trust. BRANIFY constructs holistic brand identity systems including logo usage rules, color swatches, font pairings, business stationery, social media templates, and comprehensive brand books.', 'Sparkles', 'branding', ARRAY['Adobe Illustrator', 'InDesign', 'Figma']::text[], ARRAY['Brand Guidelines PDF', 'Logo Master Suite', 'Color & Typography Kit', 'Stationery Designs', 'Social Media Templates']::text[], 'Starting price', 'Custom quote', '4–14 Days', true, false, 5, '{"title": "Brand Identity Services — BRANIFY", "description": "Transform your business into a cohesive, premium international brand with full style guidelines, stationery, and social kits."}'::jsonb, false),
  ('social-media-design', '07', 'Social Media Design', 'Engaging Instagram, LinkedIn, Facebook & YouTube ad creatives.', 'Stand out on feed algorithms with high-impact, custom social media designs tailored for Instagram, Facebook, LinkedIn, Twitter/X, and YouTube. We combine bold typography, custom graphics, and brand consistency to boost your engagement.', 'Share2', 'marketing', ARRAY['Canva', 'Photoshop', 'Figma', 'Illustrator']::text[], ARRAY['Post Graphics Pack', 'Carousel Slides', 'Ad Creatives', 'Editable Canva & Figma Templates']::text[], 'Starting price', 'Custom quote', '3–7 Days', true, false, 6, '{"title": "Social Media Design Services — BRANIFY", "description": "Eye-catching social media posts, story templates, carousel graphics, reel covers, and ad creatives that stop the scroll."}'::jsonb, false),
  ('business-presentation', '08', 'Business Presentation', 'Investor pitch decks, sales presentations & company profiles.', 'Secure funding and close high-value deals with custom-designed presentations. We turn complex data, market statistics, and business strategy into visually compelling, easy-to-digest pitch decks in PowerPoint, Google Slides, or PDF.', 'Presentation', 'branding', ARRAY['PowerPoint', 'Google Slides', 'Figma', 'Illustrator']::text[], ARRAY['Editable PowerPoint (.pptx) File', 'Google Slides Link', 'Print-Ready PDF Deck', 'Custom Graphic Assets']::text[], 'Starting price', 'Custom quote', '3–7 Days', true, false, 7, '{"title": "Business Presentation Services — BRANIFY", "description": "Captivate investors, board members, and clients with custom pitch decks, sales decks, and polished company profiles."}'::jsonb, false),
  ('seo', '09', 'SEO (Search Engine Optimization)', 'Technical, on-page, local SEO & keyword ranking strategies.', 'Drive sustainable, organic traffic to your website without relying solely on paid ads. Our SEO services cover deep technical fixes, keyword mapping, content structuring, schema markup, local SEO, and Google Search Console performance optimization.', 'Search', 'marketing', ARRAY['Google Search Console', 'Ahrefs', 'SEMrush', 'Schema.org', 'GA4']::text[], ARRAY['Technical Audit Report', 'Keyword Mapping Document', 'On-Page Meta Optimization', 'GSC & Analytics Setup']::text[], 'Starting price', 'Custom quote', '5–14 Days', true, false, 8, '{"title": "SEO (Search Engine Optimization) Services — BRANIFY", "description": "Dominate Google search results with comprehensive technical audits, keyword strategy, schema markup, and speed optimization."}'::jsonb, false),
  ('ai-solutions', '10', 'AI Solutions', 'Custom AI chatbots, workflow automation & LLM integration.', 'Leverage state-of-the-art AI technology to automate customer support, generate smart business insights, and streamline daily operations. We build custom AI applications, Gemini/OpenAI API integrations, RAG knowledge bots, and automated workflows.', 'Bot', 'ai', ARRAY['Gemini API', 'TypeScript', 'Node.js', 'Vector DB', 'Express']::text[], ARRAY['Custom AI Widget / App', 'Server Proxy & API Integration', 'Prompt Engineering Architecture', 'Admin Control Panel']::text[], 'Starting price', 'Custom quote', '5–21 Days', true, false, 9, '{"title": "AI Solutions Services — BRANIFY", "description": "Empower your business with custom AI chatbots, automated customer support, Gemini API workflows, and smart task automation."}'::jsonb, false),
  ('business-consultation', '11', 'Business Consultation', 'Strategic roadmap for digital transformation, branding & growth.', 'Unsure which technology stack to choose, how to rebrand, or how to implement AI in your operations? Sit down with BRANIFY strategy leads for an actionable consultation session that provides clear roadmaps, vendor audits, and growth blueprints.', 'TrendingUp', 'consulting', ARRAY['Google Meet', 'Strategy Blueprint', 'Audit System']::text[], ARRAY['1-on-1 Live Strategy Session', 'Custom Growth Blueprint PDF', 'Recorded Call Session', '14-Day Email Q&A Access']::text[], 'Starting price', 'Custom quote', '1-on-1 Session', true, false, 10, '{"title": "Business Consultation Services — BRANIFY", "description": "Get expert 1-on-1 strategic guidance on web technology, brand positioning, online scaling, and AI adoption for your business."}'::jsonb, false)
insert into public.portfolio_projects (slug, title, category, client, description, hero_image, gallery, technologies, challenge, solution, outcome, live_url, featured, published, sort_order, seo, archived)
values
  ('aethel-luxury', 'Aethel Luxury Timepieces', 'E-Commerce Experience', 'Aethel Horology Group', 'An interactive 3D virtual showroom and bespoke checkout experience engineered for a Swiss independent luxury horology maison.', 'linear-gradient(135deg, #181920 0%, #2A261B 50%, #0F1014 100%)', '{}'::text[], ARRAY['Web 3D Interactive Viewer', 'Custom Shopify Plus Store', 'Global Multi-Currency Engine', 'VIP Private Client Portal']::text[], '', '', 'Conversion Uplift: +54% · Avg Time on Site: 4m 18s · Annual Digital Volume: $18.4M', '', true, true, 0, '{"title": "Aethel Luxury Timepieces — Case Study | BRANIFY", "description": "An interactive 3D virtual showroom and bespoke checkout experience engineered for a Swiss independent luxury horology maison."}'::jsonb, false),
  ('synapse-ai', 'Synapse Cognitive Cloud', 'AI Platform', 'Synapse Systems Inc.', 'Next-generation AI orchestration platform with real-time vector visualization, autonomous agent workflows, and sub-millisecond telemetry.', 'linear-gradient(135deg, #10121A 0%, #1D1E2C 50%, #090A0E 100%)', '{}'::text[], ARRAY['Design System Architecture', 'Full-Stack Web App', 'Interactive Node Graph UI', 'Developer Documentation Engine']::text[], '', '', 'Active Enterprise Nodes: 140,000+ · Processing Latency: <24ms · Series B Capital: $45M', '', true, true, 1, '{"title": "Synapse Cognitive Cloud — Case Study | BRANIFY", "description": "Next-generation AI orchestration platform with real-time vector visualization, autonomous agent workflows, and sub-millisecond telemetry."}'::jsonb, false),
  ('lumina-architects', 'Lumina Spatial Architecture', 'Luxury Brand Website', 'Lumina Studio Tokyo', 'A minimalist spatial digital experience documenting international architectural monuments through smooth web transitions and architectural typography.', 'linear-gradient(135deg, #141519 0%, #232220 50%, #0B0C0E 100%)', '{}'::text[], ARRAY['Brand Identity Guidelines', 'Bespoke Custom Headless CMS', 'High-Res Image Optimization', 'Editorial Editorial Layouts']::text[], '', '', 'Global Design Awards: 6 Won · Page Speed Benchmark: 100 / 100 · Inquiry Lead Quality: +78%', '', true, true, 2, '{"title": "Lumina Spatial Architecture — Case Study | BRANIFY", "description": "A minimalist spatial digital experience documenting international architectural monuments through smooth web transitions and architectural typography."}'::jsonb, false),
  ('nexus-exchange', 'Nexus Digital Marketplace', 'Digital Marketplace', 'Nexus Global Protocols', 'High-frequency asset marketplace engineered with instant orderbook execution, WebGL data depth charts, and institutional multi-sig security.', 'linear-gradient(135deg, #0C0F14 0%, #1A2129 50%, #08090C 100%)', '{}'::text[], ARRAY['Real-Time WebSocket Engine', 'Dark-Mode Focused UI', 'Mobile Adaptive Web App', 'Institutional Security Audit']::text[], '', '', 'Monthly Trading Vol: $1.2B · Concurrent Users: 85,000+ · Crash Rate: 0.000%', '', false, true, 3, '{"title": "Nexus Digital Marketplace — Case Study | BRANIFY", "description": "High-frequency asset marketplace engineered with instant orderbook execution, WebGL data depth charts, and institutional multi-sig security."}'::jsonb, false),
  ('quantis-analytics', 'Quantis Technology Dashboard', 'Technology Dashboard', 'Quantis Financial Tech', 'Precision risk management and financial modeling platform delivering real-time portfolio simulations for tier-one hedge funds.', 'linear-gradient(135deg, #121319 0%, #25221B 50%, #0A0B0E 100%)', '{}'::text[], ARRAY['WebGL Data Visualizations', 'Dynamic Formula Builder', 'Role-Based Access Control', 'Multi-Monitor Display Mode']::text[], '', '', 'Data Points / Sec: 2.5M · Decision Speedup: 6.2x · Enterprise Retention: 99.4%', '', false, true, 4, '{"title": "Quantis Technology Dashboard — Case Study | BRANIFY", "description": "Precision risk management and financial modeling platform delivering real-time portfolio simulations for tier-one hedge funds."}'::jsonb, false),
  ('verve-ventures', 'Verve Innovation Lab', 'Creative Business Website', 'Verve Ventures Global', 'An evocative portfolio portal connecting deep-tech startups with forward-thinking sovereign wealth funds and venture syndicates.', 'linear-gradient(135deg, #16171E 0%, #221D16 50%, #090A0D 100%)', '{}'::text[], ARRAY['Custom WebGL Backgrounds', 'Pitch Deck Dynamic Hub', 'Interactive Portfolio Directory', 'Fast Automated Form Routing']::text[], '', '', 'Syndicate Deal Flow: $320M · Investor Engagement: +88% · Mobile Traffic Share: 62%', '', false, true, 5, '{"title": "Verve Innovation Lab — Case Study | BRANIFY", "description": "An evocative portfolio portal connecting deep-tech startups with forward-thinking sovereign wealth funds and venture syndicates."}'::jsonb, false)
insert into public.products (slug, name, category, description, image, price, currency, status, delivery_info, file_url, featured, sort_order, seo, archived)
values
  ('modern-saas-landing-page', 'Modern SaaS Landing Page Starter', 'Website Templates', 'A production-ready responsive landing page built with semantic HTML5, Tailwind CSS CDN, and high-contrast typography. Includes hero section with animated CTA, feature grids, pricing table toggle, testimonial cards, and an accessible FAQ accordion. Free to download and customize for personal and commercial projects.', '', 0.0, 'USD', 'active', 'License: MIT License — 100% Free for Commercial & Personal Use', '/downloads/templates/modern-saas-landing-starter.html', true, 1, '{"title": "Modern SaaS Landing Page Starter Template — 100% Free Download | BRANIFY", "description": "Download this free, high-converting HTML5 & Tailwind CSS SaaS landing page template. Clean code, fully responsive, MIT licensed."}'::jsonb, false),
  ('creative-developer-portfolio', 'Creative Developer & Designer Portfolio', 'Website Templates', 'Showcase your software engineering work, technical competencies, and client case studies with this dark-mode HTML5 & Tailwind portfolio template. Features interactive project repository cards, skills chips, career experience timeline, and a functional contact brief form structure.', '', 0.0, 'USD', 'active', 'License: MIT License — 100% Free for Commercial & Personal Use', '/downloads/templates/developer-portfolio-starter.html', false, 2, '{"title": "Developer Portfolio HTML5 Starter Template — Free Download | BRANIFY", "description": "Download a clean, modern developer & software engineer portfolio template in HTML5 and Tailwind CSS. 100% Free."}'::jsonb, false),
  ('client-master-services-agreement', 'Client Master Services Agreement (MSA) & SOW', 'Business Templates', 'A comprehensive, structured Master Services Agreement (MSA) and Statement of Work (SOW) template for digital agencies, freelance developers, and consultants. Covers scope of work, milestone payments (50/25/25), revision caps, intellectual property assignment upon final payment, confidentiality non-disclosure, and liability protections.', '', 0.0, 'USD', 'active', 'License: Free to use and adapt for personal and commercial business purposes', '/downloads/templates/client-master-services-agreement.txt', true, 3, '{"title": "Client Master Services Agreement & SOW Template — Free Download | BRANIFY", "description": "Free Master Services Agreement (MSA) and Statement of Work template for digital agencies and freelancers."}'::jsonb, false),
  ('client-discovery-project-brief', 'Client Discovery Questionnaire & Project Brief', 'Business Templates', 'Save hours in client meetings and eliminate scope creep before kick-off. This 20-question discovery template helps agencies and freelancers extract business objectives, target audience demographics, technical requirements, competitor benchmarks, and launch timeline expectations.', '', 0.0, 'USD', 'active', 'License: Free for agency, freelance, and client onboarding use', '/downloads/templates/client-discovery-project-brief.txt', false, 4, '{"title": "Client Discovery Questionnaire & Project Brief Template — Free | BRANIFY", "description": "Extract client goals, scope, and technical requirements with this 20-question discovery questionnaire template."}'::jsonb, false),
  ('ats-optimized-tech-resume', 'ATS-Optimized Tech Resume Template', 'Resume / CV Templates', 'Engineered specifically to pass Applicant Tracking Systems (ATS) algorithms. Uses clean single-column structure, standard section headers, keyword optimization placeholders, and impact-driven action verb bullet formulas ([Action] + [Context] + [Measurable Outcome %]).', '', 0.0, 'USD', 'active', 'License: Free to use and modify for personal career development', '/downloads/templates/ats-optimized-tech-resume.txt', true, 5, '{"title": "ATS-Optimized Tech Resume Template — Free Download | BRANIFY", "description": "Download this free single-column ATS-friendly resume template for software engineers, designers, and tech professionals."}'::jsonb, false),
  ('seed-startup-pitch-deck', 'Seed Startup Pitch Deck Structure & Blueprint', 'Presentation Templates', 'The battle-tested 15-slide pitch deck structure utilized by venture-backed startups to raise Pre-Seed and Seed capital. For every slide, this guide details the exact Purpose, What to Include, Key Metrics to Highlight, and Common Mistakes to avoid before pitching angel investors and VC partners.', '', 0.0, 'USD', 'active', 'License: Free for startup fundraising and pitch deck creation', '/downloads/templates/seed-startup-pitch-deck-structure.txt', true, 6, '{"title": "Seed Startup Pitch Deck Structure & Blueprint — Free Download | BRANIFY", "description": "15-slide pitch deck framework for founders raising Seed & Pre-Seed capital. Free download from BRANIFY."}'::jsonb, false),
  ('startup-runway-cashflow-model', 'Startup Runway & Cash Flow Financial Model', 'Spreadsheet Templates', 'A 12-month cash flow and runway projection spreadsheet model formatted in standard CSV. Seamlessly importable into Excel, Google Sheets, Apple Numbers, or Notion. Includes monthly beginning cash, recurring MRR, services revenue, granular operating expenses (payroll, marketing, software, cloud), net burn rate, and calculated runway months.', '', 0.0, 'USD', 'active', 'License: Free to use and adapt for personal and commercial financial modeling', '/downloads/templates/startup-runway-cashflow-model.csv', true, 7, '{"title": "Startup Runway & Cash Flow Financial Model (CSV/Excel) — Free | BRANIFY", "description": "Calculate startup burn rate, cash flow, and runway with this 12-month financial model spreadsheet. Free CSV download."}'::jsonb, false),
  ('social-media-content-calendar', 'Multi-Platform Social Media Content Calendar', 'Social Media Templates', 'Organize your brand publishing strategy across LinkedIn, Twitter/X, Instagram, TikTok, and Newsletters. This multi-channel editorial matrix spreadsheet includes fields for publishing dates, target pillars, hooks/headlines, caption copy, call-to-action triggers, visual asset statuses, and engagement goals.', '', 0.0, 'USD', 'active', 'License: Free for personal and commercial marketing management', '/downloads/templates/social-media-content-calendar.csv', false, 8, '{"title": "Multi-Platform Social Media Content Calendar (CSV) — Free Download | BRANIFY", "description": "Plan, schedule, and organize social media posts across LinkedIn, Twitter, and Instagram with this free content calendar matrix."}'::jsonb, false),
  ('agency-brand-guidelines-canva', 'Agency Brand Guidelines Presentation Deck', 'Canva Templates', 'A 25-slide Canva presentation template crafted for branding agencies and identity designers to present brand guidelines to enterprise clients. Includes slides for brand mission, typography hierarchy, primary and secondary color palettes, logo exclusion zones, photography art direction, and digital asset usage rules.', '', 0.0, 'USD', 'coming_soon', 'License: Free to edit in Canva for personal & commercial client deliverables', '', false, 9, '{"title": "Agency Brand Guidelines Canva Template — Coming Soon | BRANIFY", "description": "25-slide minimalist brand identity presentation kit in Canva. Coming soon to BRANIFY Free Templates."}'::jsonb, false),
  ('freelance-client-portal-notion', 'Freelance Client Portal & Project Hub', 'Notion Templates', 'A streamlined client portal dashboard built in Notion. Gives your clients a unified, transparent view of project milestones, asset deliverables, shared Google Drive folders, meeting notes, invoice statuses, and feedback revision logs.', '', 0.0, 'USD', 'coming_soon', 'License: Free to duplicate and share with unlimited clients', '', false, 10, '{"title": "Freelance Client Portal Notion Template — Coming Soon | BRANIFY", "description": "All-in-one client dashboard in Notion for asynchronous project delivery and feedback. Coming soon to BRANIFY."}'::jsonb, false)
